  "inlineSchema": "// -----------------------------------------------------\n// Prisma Schema — SQLite\n// Stages: raw, processed, sorted (append-only: ledger + transport)\n// -----------------------------------------------------\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -------------------- Enums --------------------------\n\nenum Size {\n  LUMPS\n  CHIPS\n  FINE\n  ANY // unify 3s/4s: raw uses ANY\n}\n\nenum Shade {\n  WHITE\n  GREY\n  LIGHTGREY\n  GREEN\n  MIXED\n}\n\nenum LedgerReason {\n  DIRECT\n  PROCESS\n  TRANSPORT\n  REVERSAL\n  ADJUST\n}\n\nenum TransportEventType {\n  DISPATCH\n  RECEIVE\n  CANCEL\n}\n\n// -------------------- Reference ----------------------\n\nmodel Supplier {\n  id   Int    @id @default(autoincrement())\n  name String\n  code String @unique\n\n  // processed back-relations\n  processedLedgerRows    ProcessedLedger[]    @relation(\"SupplierToProcessedLedger\")\n  processedTransportRows ProcessedTransport[] @relation(\"SupplierToProcessedTransport\")\n\n  // raw back-relations\n  rawLedgerRows    RawLedger[]    @relation(\"SupplierToRawLedger\")\n  rawTransportRows RawTransport[] @relation(\"SupplierToRawTransport\")\n\n  // sorted back-relations\n  sortedLedgerRows    SortedLedger[]    @relation(\"SupplierToSortedLedger\")\n  sortedTransportRows SortedTransport[] @relation(\"SupplierToSortedTransport\")\n}\n\n// -------------------- processed (stage) ---------------\n\nmodel ProcessedLedger {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  mmaCode     String?\n  stationCode String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToProcessedLedger\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size\n\n  qtyDelta Float\n  reason   LedgerReason\n  linkId   String?\n  meta     Json?\n\n  @@index([mmaCode, createdAt])\n  @@index([mmaCode, supplierId, shade, size])\n  @@index([linkId])\n  @@map(\"processed_ledger\")\n}\n\nmodel ProcessedTransport {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  transportId String\n  type        TransportEventType\n\n  fromMmaCode     String?\n  toMmaCode       String?\n  fromStationCode String?\n  toStationCode   String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToProcessedTransport\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size\n\n  qty    Float\n  amount Int?\n  meta   Json?\n\n  @@unique([transportId, type])\n  @@index([transportId])\n  @@index([fromMmaCode, createdAt])\n  @@index([toMmaCode, createdAt])\n  @@map(\"processed_transport\")\n}\n\n// -------------------- raw (stage) ---------------------\n\nmodel RawLedger {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  mmaCode     String\n  stationCode String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToRawLedger\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size // will be ANY for raw\n\n  qtyDelta Float\n  reason   LedgerReason\n  linkId   String?\n  meta     Json?\n\n  @@index([mmaCode, createdAt])\n  @@index([mmaCode, supplierId, shade, size])\n  @@index([linkId])\n  @@map(\"raw_ledger\")\n}\n\nmodel RawTransport {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  transportId String\n  type        TransportEventType\n\n  fromMmaCode     String?\n  toMmaCode       String?\n  fromStationCode String?\n  toStationCode   String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToRawTransport\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size // ANY for raw\n\n  qty    Float\n  amount Int?\n  meta   Json?\n\n  @@unique([transportId, type])\n  @@index([transportId])\n  @@index([fromMmaCode, createdAt])\n  @@index([toMmaCode, createdAt])\n  @@map(\"raw_transport\")\n}\n\n// -------------------- sorted (stage) ------------------\n\nmodel SortedLedger {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  mmaCode     String\n  stationCode String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToSortedLedger\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size\n\n  qtyDelta Float\n  reason   LedgerReason\n  linkId   String?\n  meta     Json?\n\n  @@index([mmaCode, createdAt])\n  @@index([mmaCode, supplierId, shade, size])\n  @@index([linkId])\n  @@map(\"sorted_ledger\")\n}\n\nmodel SortedTransport {\n  id        Int      @id @default(autoincrement())\n  createdAt DateTime @default(now())\n\n  transportId String\n  type        TransportEventType\n\n  fromMmaCode     String?\n  toMmaCode       String?\n  fromStationCode String?\n  toStationCode   String?\n\n  supplierId Int\n  supplier   Supplier @relation(\"SupplierToSortedTransport\", fields: [supplierId], references: [id])\n\n  shade Shade\n  size  Size\n\n  qty    Float\n  amount Int?\n  meta   Json?\n\n  @@unique([transportId, type])\n  @@index([transportId])\n  @@index([fromMmaCode, createdAt])\n  @@index([toMmaCode, createdAt])\n  @@map(\"sorted_transport\")\n}\n\nmodel process_tbl {\n  id              Int      @id @default(autoincrement())\n  createdAt       DateTime @default(now())\n  // identity\n  processId       String   @unique // same id linked in Stock.withdraw/deposit linkId\n  processType     String // \"PROCESSING\" (room to add others later)\n  // bridge RAW -> PROCESSED\n  fromMmaCode     String // e.g., \"ABS_RAW\"\n  toMmaCode       String // e.g., \"ABS_PROCESSED\"\n  supplierId      Int\n  fromStationCode String?\n  toStationCode   String?\n  // source (one RAW slot)\n  sourceShade     String\n  sourceSize      String // \"ANY\" allowed; use tons only\n  sourceQtyT      Decimal // tons consumed\n  // targets (many PROCESSED slots)\n  targetsQtyT     Decimal // Σ of target tons\n  targets         Json // [{ shade, size, qtyT }, ...]\n  // status\n  status          String // \"SUCCESS\" | \"ROLLED_BACK\" | \"FAILED\"\n  error           String? // captured error message when not SUCCESS\n  meta            Json?\n\n  @@index([fromMmaCode, toMmaCode, supplierId])\n}\n\nmodel screening_tbl {\n  id          Int       @id @default(autoincrement())\n  createdAt   DateTime  @default(now())\n  committedAt DateTime?\n\n  // idempotency / identity\n  processId   String  @unique\n  processType String? // \"SORTING\" (optional, for readability)\n\n  // strict pair: PROCESSED -> SORTED\n  fromMmaCode     String // e.g., \"ABS_PROCESSED\"\n  toMmaCode       String // e.g., \"ABS_SORTED\"\n  supplierId      Int\n  fromStationCode String?\n  toStationCode   String?\n\n  // source (PROCESSED)\n  fromShade String\n  fromSize  String\n  // destination (SORTED)\n  toShade   String\n  toSize    String\n\n  // quantity (tons) — identical both sides\n  qtyT Decimal\n\n  // NEW: top-level attributes for this process\n  ht      Int? // e.g., 55\n  wastage Decimal? // percent (0..100). External funcs can map/interpret.\n\n  // ledger linkage (for audit)\n  withdrawLedgerId String\n  depositLedgerId  String\n\n  // outcome\n  status String // \"SUCCESS\" | \"ROLLED_BACK\" | \"FAILED\"\n  error  String?\n  // keep meta for any extras beyond ht/wastage\n  meta   Json?\n\n  @@index([fromMmaCode, toMmaCode, supplierId])\n  @@index([createdAt])\n}\n",
